func BenchmarkClosure_Argptr(b *testing.B) {
	var sum int
	var step func(i *int)
	var cond func(i int) bool

	step = func(i *int) { *i++ }
	cond = func(i int) bool { return i < 100 }

	for i := 0; b.Loop(); step(&i) {
		if cond(i) {
			sum += i
		} else {
			i = 0
		}
	}
	b.Log(sum)
}
func BenchmarkClosure_Arg(b *testing.B) {
	var sum int
	var step func(i int) int
	var cond func(i int) bool

	step = func(i int) int { return i + 1 }
	cond = func(i int) bool { return i < 100 }

	for i := 0; b.Loop(); i = step(i) {
		if cond(i) {
			sum += i
		} else {
			i = 0
		}
	}
	b.Log(sum)
}

func BenchmarkClosure_Default(b *testing.B) {
	var sum int
	var step func()
	var cond func() bool
	var i int
	step = func() { i++ }
	cond = func() bool { return i < 100 }

	for i = 0; b.Loop(); step() {
		if cond() {
			sum += i
		} else {
			i = 0
		}
	}
	b.Log(sum)
}
func BenchmarkClosure_DoubleClosure(b *testing.B) {
	var sum int
	var step func()
	var cond func() bool
	var execute func()
	var i int
	step = func() { i++ }
	cond = func() bool { return i < 100 }
	execute = func() {
		if cond() {
			sum += i
		} else {
			i = 0
		}
		step()
	}
	for b.Loop() {
		execute()
	}
	b.Log(sum)
}

func BenchmarkClosure_NoClosure(b *testing.B) {
	var sum int
	var i int

	for i = 0; b.Loop(); i++ {
		if i < 100 {
			sum += i
		} else {
			i = 0
		}
	}
	b.Log(sum)
}
